IF NOT EXISTS (SELECT 1 FROM Sellers WHERE Name = 'evidea') INSERT INTO Sellers (Name) VALUES ('evidea');
IF NOT EXISTS (SELECT 1 FROM Sellers WHERE Name = 'mion') INSERT INTO Sellers (Name) VALUES ('mion');
IF NOT EXISTS (SELECT 1 FROM Sellers WHERE Name = 'macrocenter') INSERT INTO Sellers (Name) VALUES ('macrocenter');
IF NOT EXISTS (SELECT 1 FROM Sellers WHERE Name = 'hakmarexpress') INSERT INTO Sellers (Name) VALUES ('hakmarexpress');

